```go
package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"os"

	"github.com/avro/go-avro"
)

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run parser.go <source_file> <struct_name>")
		return
	}

	sourceFile := os.Args[1]
	structName := os.Args[2]

	// Read the content of the source file
	content, err := ioutil.ReadFile(sourceFile)
	if err != nil {
		fmt.Printf("Error reading file: %v\n", err)
		return
	}
	defer func() { _ = ioutil.CloseReader(ioutil.NopCloser(bytes.NewReader(content))) }()

	var structDef map[string]interface{}
	err = json.Unmarshal(content, &structDef)
	if err != nil {
		fmt.Printf("Error unmarshalling JSON: %v\n", err)
		return
	}

	// Parse the struct definition into an Avro schema
	schema, err := avro.ParseSchema(structDef)
	if err != nil {
		fmt.Printf("Error parsing Avro schema: %v\n", err)
		return
	}

	// Write the Avro schema to a file
	file, err := os.Create(fmt.Sprintf("%s.avsc", structName))
	if err != nil {
		fmt.Printf("Error creating file: %v\n", err)
		return
	}
	defer func() { _ = file.Close() }()

	json.NewEncoder(file).Encode(schema)
	fmt.Printf("Generated Avro schema written to %s.avsc\n", structName)
}
```

